// PROTOTYPE - NOT FOR PRODUCTION
// Voice bake: index.html's fixed CAPCOM/CDR/LMP lines -> manifest -> Windows OneCore TTS (synth.ps1) -> walkie-talkie
// filter (radio.sh, ffmpeg) -> assets/data/voice.js. Steps:
//   node tools/voice/bake.js manifest <work>     writes <work>/manifest.json from index.html
//   powershell -File tools/voice/synth.ps1 <work>/manifest.json <work>/raw
//   (per clip) ffmpeg silenceremove -> <work>/trim/<id>.wav, then bash tools/voice/radio.sh ffmpeg <trim wav> <work>/radio/<id>.mp3
//   node tools/voice/bake.js pack <work>         writes assets/data/voice.js (base64 mp3 keyed by the exact subtitle text)
const fs = require('fs'), path = require('path');
const game = path.join(__dirname, '..', '..'), [cmd, work] = process.argv.slice(2);
if (cmd === 'manifest') {
  const h = fs.readFileSync(path.join(game, 'index.html'), 'utf8'), s = new Set();
  for (const m of h.matchAll(/'((?:CAPCOM|CDR|LMP): [^'$]*)'|"((?:CAPCOM|CDR|LMP): [^"$]*)"|`((?:CAPCOM|CDR|LMP): [^`$]*)`/g)) s.add(m[1] || m[2] || m[3]);
  const out = [...s].map((t, i) => ({ id: 'v' + String(i).padStart(2, '0'), who: t.split(':')[0], text: t, say: t.slice(t.indexOf(':') + 2) }));
  fs.writeFileSync(path.join(work, 'manifest.json'), JSON.stringify(out, null, 1)); console.log(out.length, 'lines');
} else if (cmd === 'pack') {
  const man = JSON.parse(fs.readFileSync(path.join(work, 'manifest.json'), 'utf8'));
  let js = '// PROTOTYPE - NOT FOR PRODUCTION\n// Radio voice clips: Windows OneCore TTS (CAPCOM Mark, CDR David, LMP Zira) through a walkie-talkie filter.\n' +
    '// Generated by tools/voice/bake.js; keyed by the exact subtitle text so what you hear is what you read. See assets/provenance.yaml.\nwindow.VOICE_CLIPS = {\n';
  for (const l of man) js += `  ${JSON.stringify(l.text)}: '${fs.readFileSync(path.join(work, 'radio', l.id + '.mp3')).toString('base64')}',\n`;
  fs.writeFileSync(path.join(game, 'assets', 'data', 'voice.js'), js + '};\n'); console.log('packed', man.length);
}
